package Patterns;
import java.util.Scanner;

public class SeriesInput {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
        Scanner sc=new Scanner(System.in);
        System.out.println("Enter the series of number: ");
        int a1=sc.nextInt();
        System.out.println("your expected result is--> "+ (a1-3));
        int b1=sc.nextInt();
        System.out.println("your expected result is--> "+ (b1-4));
        int c1=sc.nextInt();
        System.out.println("your expected result is--> "+ (c1-1));
        int d1=sc.nextInt();
        System.out.println("your expected result is--> "+ (d1));
        int e1=sc.nextInt();
        System.out.println("your expected result is--> "+ (e1-1));
        int f1=sc.nextInt();
        System.out.println("your expected result is--> "+ (f1));
        
        
        
	}

}
